<?php
namespace App\Http\Controllers;
use App\Models\Content; use App\Models\Appointment; use App\Models\ContactMessage; use Illuminate\Http\Request;
class PublicController extends Controller {
 public function listing($type){$map=['doctors'=>'doctor','departments'=>'department','hospitals'=>'hospital','packages'=>'package','news'=>'news','gallery'=>'gallery','offers'=>'offer','videos'=>'video','journal'=>'journal','sister-concerns'=>'sister_concern','accreditation'=>'accreditation','md-writeup'=>'md_writeup','about'=>'about'];abort_unless(isset($map[$type]),404);$kind=$map[$type];$query=Content::type($kind)->where('is_published',1);if($type==='doctors'){if(request('q'))$query->where('title','like','%'.request('q').'%');if(request('department'))$query->where('extra->department',request('department'));if(request('hospital'))$query->where('extra->hospital',request('hospital'));}$items=$query->latest()->paginate(20)->withQueryString();return view('listing',compact('items','type'));}
 public function detail($type,$slug){$map=['doctors'=>'doctor','departments'=>'department','hospitals'=>'hospital','packages'=>'package','news'=>'news','gallery'=>'gallery','offers'=>'offer','videos'=>'video','journal'=>'journal','sister-concerns'=>'sister_concern','accreditation'=>'accreditation','md-writeup'=>'md_writeup','about'=>'about'];abort_unless(isset($map[$type]),404);$item=Content::type($map[$type])->where('slug',$slug)->where('is_published',1)->firstOrFail();$doctors=$type==='departments'?Content::type('doctor')->where('extra->department',$item->title)->get():collect();return view('detail',compact('item','type','doctors'));}
 public function appointment(){return view('appointment',['doctors'=>Content::type('doctor')->where('is_published',1)->get()]);}
 public function saveAppointment(Request $r){$data=$r->validate(['patient_name'=>'required|string|max:120','phone'=>'required|string|max:30','email'=>'nullable|email|max:150','doctor_id'=>'nullable|exists:contents,id','appointment_date'=>'required|date|after_or_equal:today','message'=>'nullable|string|max:2000']);Appointment::create($data);return back()->with('success','Your appointment request has been received.');}
 public function contact(){return view('contact');}
 public function saveContact(Request $r){$data=$r->validate(['name'=>'required|string|max:120','email'=>'required|email','phone'=>'nullable|string|max:30','subject'=>'nullable|string|max:180','message'=>'required|string|max:3000']);ContactMessage::create($data);return back()->with('success','Your message has been sent.');}
 public function search(Request $r){$q=$r->string('q')->toString();$items=Content::where('is_published',1)->whereIn('type',['doctor','department','hospital','package','news'])->where('title','like','%'.$q.'%')->paginate(20);return view('search',compact('items','q'));}
 public function sitemap(){ $items=Content::where('is_published',1)->get();$paths=['doctor'=>'doctors','department'=>'departments','hospital'=>'hospitals','package'=>'packages','news'=>'news','gallery'=>'gallery','offer'=>'offers','video'=>'videos','journal'=>'journal','sister_concern'=>'sister-concerns','accreditation'=>'accreditation','md_writeup'=>'md-writeup','about'=>'about'];return response()->view('sitemap',compact('items','paths'))->header('Content-Type','application/xml');}
}
